async function run() {
  const out: any = {};
  const S = (cmd: string, timeout=20) => Developer.shell({command: cmd, network: true, timeout_secs: timeout});
  const t = (u: string) => `curl -s -o /dev/null --max-time 6 -w "%{http_code} dns=%{time_namelookup}s conn=%{time_connect}s tls=%{time_appconnect}s ttfb=%{time_starttransfer}s total=%{time_total}s" ${u} 2>&1; echo rc=$?`;

  // hermit release HEAD only (302? size?)
  out.hermit = await S('curl -sIL --max-time 6 -w "FINAL=%{url_effective} code=%{http_code} conn=%{time_connect}s total=%{time_total}s" https://github.com/cashapp/hermit/releases/download/2025-01-24/hermit-2025.01.24-1-x86_64-apple-darwin.pkg.gz 2>&1 | head -40; echo rc=$?');
  out.pypi = await S(t('https://pypi.org/simple/'));
  out.npm = await S(t('https://registry.npmjs.org/'));
  out.taobao_npm = await S(t('https://registry.npmmirror.com/'));
  out.aliyun = await S(t('https://mirrors.aliyun.com/'));
  out.tuna = await S(t('https://mirrors.tuna.tsinghua.edu.cn/pypi/web/simple/'));
  out.done = true;
  return out;
}

