async function run() {
  const out: any = {};
  const S = (cmd: string, timeout=30) => Developer.shell({command: cmd, network: true, timeout_secs: timeout});
  const w = '%{http_code} dns=%{time_namelookup}s conn=%{time_connect}s tls=%{time_appconnect}s ttfb=%{time_starttransfer}s total=%{time_total}s size=%{size_download} speed=%{speed_download}';

  out.github_10s = await S(`curl -s -o /dev/null --max-time 10 -w "${w}" https://github.com 2>&1; echo rc=$?`);
  out.nc_github = await S('nc -z -G 6 github.com 443; echo rc=$?');
  out.nc_google = await S('nc -z -G 6 www.google.com 443; echo rc=$?');
  out.tcp53 = await S("python3 -c \"import socket\ntry:\n  s=socket.create_connection(('100.100.100.100',53),3); print('TCP53 ok'); s.close()\nexcept Exception as e: print('TCP53 fail:',e)\" 2>&1");
  out.udp53 = await S("python3 -c \"import socket\ns=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(3)\npkt=b'\\x12\\x34\\x01\\x00\\x00\\x01\\x00\\x00\\x00\\x00\\x00\\x07github\\x03com\\x00\\x00\\x01\\x00\\x01'\ntry:\n  s.sendto(pkt, ('100.100.100.100',53)); print('UDP53 sent')\n  d,addr=s.recvfrom(4096); print('UDP53 reply bytes=',len(d))\nexcept Exception as e: print('UDP53 fail:',e)\" 2>&1");
  out.finished = true;
  return out;
}

