async function run() {
  const out: any = {};
  const S = (cmd: string, timeout=20) => Developer.shell({command: cmd, network: true, timeout_secs: timeout});

  // Is port 7897 actually listening?
  out.proxy7897 = await S('lsof -i :7897 2>/dev/null | head -5; echo ---; nc -z -G 2 127.0.0.1 7897; echo rc=$?');

  // Try github over port 80 (plain HTTP)
  out.gh_80 = await S('curl -s -o /dev/null --max-time 6 -w "code=%{http_code} conn=%{time_connect}s ttfb=%{time_starttransfer}s total=%{time_total}s size=%{size_download}" http://github.com 2>&1; echo rc=$?');

  // Try hermit release via port 80? no, releases redirect to objects... test objects endpoint
  out.gh_objects = await S('nc -z -G 4 objects.githubusercontent.com 443; echo rc443=$?');
  out.gh_objects_80 = await S('nc -z -G 4 objects.githubusercontent.com 80; echo rc80=$?');

  // Domestic large file throughput (use a known large file on aliyun)
  out.dom_big = await S("curl -s -r 0-2097151 --max-time 10 -o /dev/null -w 'code=%{http_code} size=%{size_download}B speed=%{speed_download}Bps total=%{time_total}s' 'https://mirrors.aliyun.com/node/v22.0.0/node-v22.0.0.pkg' 2>&1; echo rc=$?");

  // Confirm pypi throughput was ~50KB/s
  out.pypi_small = await S("curl -s -r 0-204800 --max-time 10 -o /dev/null -w 'code=%{http_code} size=%{size_download}B speed=%{speed_download}Bps total=%{time_total}s' 'https://pypi.org/simple/' 2>&1; echo rc=$?");

  out.finished = true;
  return out;
}

