{"code":"async function run() {
  const out: any = {};
  const S = (cmd: string, timeout=40) => Developer.shell({command: cmd, network: true, timeout_secs: timeout});

  // 1) flakiness check: retry github/google
  out.gh_retry = await S('for i in 1 2 3; do curl -s -o /dev/null --max-time 5 -w "try$i %{http_code} conn=%{time_connect}s\\n" https://github.com; done; echo rc=$?');
  out.ggl_retry = await S('for i in 1 2 3; do curl -s -o /dev/null --max-time 5 -w "try$i %{http_code} conn=%{time_connect}s\\n" https://www.google.com; done; echo rc=$?');
  out.gh_port80 = await S('nc -z -G 4 github.com 80; echo rc80=$?');
  out.baidu_ctrl = await S('nc -z -G 4 www.baidu.com 443; echo rc=$?');

  // 2) resolve+connect github, print IP
  out.py_connect = await S("python3 -c \"import socket\nfor d in ['github.com','www.google.com']:\n    try:\n        ip=socket.gethostbyname(d)\n        s=socket.create_connection((d,443),6); print(d,ip,'CONNECT_OK'); s.close()\n    except Exception as e: print(d,ip if 'ip' in dir() else '?','FAIL',e)\" 2>&1 | grep -v xcrun");

  // 3) pypi slow transfer check: measure real throughput on pypi.org/simple/
  out.pypi_speed = await S("curl -s --max-time 15 -o /dev/null -w 'code=%{http_code} total=%{time_total}s size=%{size_download} speed=%{speed_download}Bps' https://pypi.org/simple/; echo rc=$?");
  // domestic large-file throughput reference (aliyun OSS public sample)
  out.dom_big = await S("curl -s -r 0-1048575 --max-time 10 -o /dev/null -w 'code=%{http_code} size=%{size_download} speed=%{speed_download}Bps' https://mirrors.aliyun.com/python/3.13/3.13.1/Python-3.13.1.tar.xz; echo rc=$?");

  // 4) system proxy settings
  out.sysproxy = await S("networksetup -getwebproxy Wi-Fi 2>/dev/null; networksetup -getsecurewebproxy Wi-Fi 2>/dev/null; echo ---; networksetup -getautoproxystate Wi-Fi 2>/dev/null; echo done");
  out.ifconfig = await S('ifconfig 2>/dev/null | grep -E "^utun|inet " | head -12');
  out.finished = true;
  return out;
}"}

