async function run() {
  const out: any = {};
  const S = (cmd: string, timeout=20) => Developer.shell({command: cmd, network: true, timeout_secs: timeout});

  // Verify: small GET from github (the 404 page is tiny) vs large page
  out.gh_head = await S('curl -sI --max-time 8 -w "\\ncode=%{http_code} conn=%{time_connect}s ttfb=%{time_starttransfer}s total=%{time_total}s size=%{size_download}B speed=%{speed_download}Bps" https://github.com/cashapp/hermit/releases 2>&1 | tail -3; echo rc=$?');

  // Try a known real GitHub release (use a small one - a .txt or .tar.gz from a popular repo)
  out.gh_small_rel = await S('curl -sI --max-time 8 -w "\\ncode=%{http_code} conn=%{time_connect}s ttfb=%{time_starttransfer}s total=%{time_total}s" https://github.com/actions/checkout/releases 2>&1 | tail -3; echo rc=$?');

  // Confirm proxy reachability for google (route through local clash)
  out.via_proxy_google = await S('curl -s -o /dev/null --max-time 8 --proxy http://127.0.0.1:7897 -w "code=%{http_code} conn=%{time_connect}s total=%{time_total}s" https://www.google.com 2>&1; echo rc=$?');
  out.via_proxy_github = await S('curl -s -o /dev/null --max-time 8 --proxy http://127.0.0.1:7897 -w "code=%{http_code} conn=%{time_connect}s total=%{time_total}s" https://github.com 2>&1; echo rc=$?');

  // Confirm: domestic speed reference (1MB range from domestic CDN)
  out.dom_1mb = await S('curl -s -r 0-1048575 --max-time 8 -o /dev/null -w "code=%{http_code} size=%{size_download}B speed=%{speed_download}Bps total=%{time_total}s" "https://registry.npmmirror.com/-/binary/registry.npmjs.org/node/latest-v22.x/v22.11.0/node-v22.11.0-linux-x64.tar.xz" 2>&1; echo rc=$?');

  // Try github objects CDN (where release files actually come from)
  out.gh_objects = await S('curl -s -o /dev/null --max-time 8 -w "code=%{http_code} conn=%{time_connect}s ttfb=%{time_starttransfer}s total=%{time_total}s" https://objects.githubusercontent.com 2>&1; echo rc=$?');

  out.finished = true;
  return out;
}

