  out.py_connect = await S("python3 -c \"import socket\nfor d in ['github.com','www.google.com']:\n    try:\n        ip=socket.gethostbyname(d)\n        s=socket.create_connection((d,443),6); print(d,ip,'CONNECT_OK'); s.close()\n    except Exception as e: print(d,ip if 'ip' in dir() else '?','FAIL',e)\" 2>&1 | grep -v xcrun");

