  // Check release-assets reachability
  out.rel_assets = await S('nc -z -G 4 release-assets.githubusercontent.com 443; echo rc=$?');
  out.rel_assets_80 = await S('nc -z -G 4 release-assets.githubusercontent.com 80; echo rc=$?');

  // GitHub HTTPS via local clash proxy: measure 1MB
  out.gh_proxy_1mb = await S('curl -s --proxy http://127.0.0.1:7897 -r 0-1048575 --max-time 15 -o /dev/null -w "code=%{http_code} size=%{size_download}B speed=%{speed_download}Bps total=%{time_total}s" https://github.com/cashapp/hermit/releases/download/v0.53.0/hermit-darwin-arm64.gz 2>&1; echo rc=$?');

  // Domestic: aliyun pypi 1MB (valid large URL)
  out.dom_1mb = await S('curl -s -r 0-1048575 --max-time 10 -o /dev/null -w "code=%{http_code} size=%{size_download}B speed=%{speed_download}Bps total=%{time_total}s" "https://mirrors.aliyun.com/pypi/packages/3.13/3.13.0/Python-3.13.0.tar.xz" 2>&1; echo rc=$?');

  // Confirm github.com 443 is the blocked port (not domain-wide)
  out.gh443 = await S('nc -z -G 6 github.com 443 2>&1; echo rc=$?');
  out.gh80 = await S('nc -z -G 4 github.com 80 2>&1; echo rc=$?');
  out.ggl443 = await S('nc -z -G 6 www.google.com 443 2>&1; echo rc=$?');
  out.ggl80 = await S('nc -z -G 4 www.google.com 80 2>&1; echo rc=$?');

  // PyPI 443
  out.pypi443 = await S('nc -z -G 4 pypi.org 443 2>&1; echo rc=$?');

  out.finished = true;
  return out;
}"}

